import{_ as r,l as i,o as e,c as n,v as l,p as s,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"套刻预算分解","description":"","frontmatter":{"title":"套刻预算分解","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/overlay-budget.md","filePath":"litho/overlay-budget.md","lastUpdated":1789023840000}'),h={name:"litho/overlay-budget.md"};function S(c,a,A,u,m,_){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="套刻预算分解" tabindex="-1">套刻预算分解 <a class="header-anchor" href="#套刻预算分解" aria-label="Permalink to &quot;套刻预算分解&quot;">​</a></h1><div class="epigraph"><p>产品上那一个纳米数，是扫描机、掩模与工艺各交一截再合成的；不分解就只会去拧工件台。</p><footer>—— 据 Levinson 对 overlay 误差源的划分，以及 ASML 对 on-product overlay 预算的公开讲义整理</footer></div><p><a href="/litho/litho-overlay">上一课</a>已经把对准与套刻分开，并指出贡献来自设备、掩模与工艺。缺口是：还没有一张能加减的预算——哪些项可校正、哪些项只能平方和，单机规格怎样叠成产品上套刻。本课做分解。<a href="/litho/twinscan-dual-stage">双工件台</a>怎样加密网格，是下一课的产能架构，不在本课重讲传感器商标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口语里的「套刻 3 nm」往往是产品上残差的某个统计。上一课警告过：单机、匹配、产品上不是同一个数。缺口接着是：产品上那一包，能不能拆成扫描机指纹、掩模写误差、晶圆变形与计量噪声，从而决定该买机台、改掩模、还是改薄膜应力。不拆，所有超差都会被送到扫描机应用工程师那里。</p><p>ASML 公开材料把 on-product overlay 写成设备项与工艺/掩模项的组合：有的系统误差进高阶校正环，残差才进 \\(3\\sigma\\)。把已经能校正的镜头加热当成「机台做不到」，会高估硬件缺口；把标记不对称当成「再买一台更准的」，会低估工艺。</p><h3 id="可校正与不可校正" tabindex="-1">可校正与不可校正 <a class="header-anchor" href="#可校正与不可校正" aria-label="Permalink to &quot;可校正与不可校正&quot;">​</a></h3><p>线性放大、旋转、平移，以及若干场内/场间高阶项，曝光前可以按网格扣掉。预算里要单列「校正后残差」。扫描同步、不可建模的高阶畸变、掩模随机写入、刻蚀引起的标记伪位移，校正环吃不掉。混在一个 RSS 里而不声明哪些已扣，数字会看起来永远差一截。</p><p><span class="marginnote">匹配套刻（两台机混跑）要把两台的指纹差加进预算，不能只用单机单卡盘的演示值。产线混跑 DUV 与 EUV 时，还要单独的交叉匹配项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上把套刻矢量场的残差按来源记账，独立项用平方和（RSS），已知相关项先合并再进 RSS。典型三块：</p><ul><li><strong>扫描机</strong>：工件台与编码器、扫描同步、镜头畸变与加热、对准传感器噪声与残余。单机 overlay 规格主要罩这一块（在受控标记上）。</li><li><strong>掩模</strong>：写位置误差、掩模加热与夹持变形、pellicle 应力。\\(4\\times\\) 缩比把掩模上的纳米除以四落到晶圆，但 MEEF 式的「位置放大」在套刻上通常仍按几何缩比，不要把 CD 的 MEEF 直接抄过来。</li><li><strong>工艺</strong>：薄膜应力导致的晶圆翘曲与面内变形、刻蚀/CMP 造成的套刻标记不对称、前层参考的稳定性。这一块往往在产品上大于新手对「台子」的想象。</li></ul><p>计量本身占一项：套刻机的精度与标记质量。预算必须写清是 IBO 还是衍射套刻、量的是光刻后还是刻蚀后标记——后课计量会展开，本课只要求占一格。场内（intra-field：镜头、掩模、扫描同步）与场间（inter-field：晶圆网格、工件台、工艺翘曲）也要拆行：前者换照明或换掩模会动，后者换工艺层会动。混成一个 \\(3\\sigma\\) 会让你同时去拧镜头加热和薄膜应力。</p>',13)),(e(),s(E,null,{default:t(()=>[d(o,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20RSS%5B%22RSS%20%E5%90%88%E6%88%90%22%5D%0A%20%20MSK%5B%22%E6%8E%A9%E6%A8%A1%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20RSS%0A%20%20PRC%5B%22%E5%B7%A5%E8%89%BA%E5%8F%98%E5%BD%A2%20%2F%20%E6%A0%87%E8%AE%B0%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20RSS%0A%20%20MET%5B%22%E8%AE%A1%E9%87%8F%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20RSS%0A%20%20RSS%20--%3E%20OPO%5B%22%E4%BA%A7%E5%93%81%E4%B8%8A%E5%A5%97%E5%88%BB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>套刻是层间相对位置。扫描机项通过曝光瞬间的坐标把图形放下；掩模项把 reticule 上的位置误差缩放到晶圆；工艺项把「你以为对准了的标记」相对器件图形挪走，或把整片网格弯掉。LELE 两次曝光的相对位移直接改节距，预算要按那一层的图形策略加严，不能套用植入层的配额。</p><p>校正环减少系统项的均值，不消灭随机与未建模高阶。镜头加热随产率与照明模式变，稳态指纹与第一批片不同，预算要含瞬态。晶圆热与浸没水的瞬态变形同样。把某一天的最佳校正配方当成物理下限，会在换层、换照明时超差。RSS 默认项之间不相关；工艺翘曲与对准网格若同源（同一应力场），应先合成再进 RSS，否则会重复记账或漏相关。</p><p><span class="marginnote">不要把产品规格书上的单机 overlay 与芯片两层之间的套准排在同一张「谁更准」的表里。定义不同，预算的输入就不同。ASML 公开讲义强调的正是 on-product 与 tool overlay 的差别。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出「7 nm 必须 2 nm 套刻」的换算，也不把某次 SPIE 演示的分解百分比写成所有厂的宇宙常数。具体纳米配额由工艺包与设计规则定。不要发明 arXiv 来「证明」RSS 公式——它是误差合成的工程惯例，Levinson 与设备公开讲义都这么用。</p><p>下一课的双工件台改变的是「测量点够不够、要不要占曝光时间」，不改变本课三块的物理定义。扫描同步作为扫描机项的一部分，细节在步进器/扫描机课之后还会再拆狭缝。</p><p>分解的目的是选执行器：机台指纹进校正环，掩模进写件与 pellicle，工艺项进薄膜与标记设计。一张不分解的 \\(3\\sigma\\) 只会把所有人派去拧工件台。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>产品上套刻 = 校正后的扫描机 + 掩模 + 工艺 + 计量，独立项 RSS。</li><li>先扣可校正系统项，再谈硬件是否够准。</li><li>工艺标记不对称与晶圆变形不能靠换机台完全消掉。</li><li>单机、匹配、产品上、交叉匹配，各进预算的不同行。</li><li>场内与场间要分行：换照明动前者，换工艺层动后者。</li><li>出处：Levinson, <em>Principles of Lithography</em>；ASML overlay / on-product overlay 公开讲义与产品说明。</li></ul>',10))])}const v=r(h,[["render",S]]);export{f as __pageData,v as default};
